do $$ begin
if (select data#>>'{image}' from public.cms_sections where page_id='company--about-us' and key='sectionOne') is distinct from '/our-company/about-us/section-1-main-image.png' then raise exception 'Incorrect image: {image}'; end if;
if (select data#>>'{image}' from public.cms_sections where page_id='company--leadership' and key='sectionOne') is distinct from '/our-company/leadership/section-1-main-image.png' then raise exception 'Incorrect image: {image}'; end if;
if (select data#>>'{image}' from public.cms_sections where page_id='company--certifications-recognitions' and key='sectionOne') is distinct from '/our-company/certifications-and-recognitions/section-1-main-image.png' then raise exception 'Incorrect image: {image}'; end if;
if (select data#>>'{image}' from public.cms_sections where page_id='company--about-us' and key='sectionFive') is distinct from '/our-company/about-us/section-5-main-image.png' then raise exception 'Incorrect image: {image}'; end if;
if (select data#>>'{members,0,image}' from public.cms_sections where page_id='company--leadership' and key='sectionFour') is distinct from '/our-company/leadership/person-1.png' then raise exception 'Incorrect image: {members,0,image}'; end if;
if (select data#>>'{members,1,image}' from public.cms_sections where page_id='company--leadership' and key='sectionFour') is distinct from '/our-company/leadership/person-2.png' then raise exception 'Incorrect image: {members,1,image}'; end if;
if (select data#>>'{members,2,image}' from public.cms_sections where page_id='company--leadership' and key='sectionFour') is distinct from '/our-company/leadership/person-3.png' then raise exception 'Incorrect image: {members,2,image}'; end if;
if (select data#>>'{members,3,image}' from public.cms_sections where page_id='company--leadership' and key='sectionFour') is distinct from '/our-company/leadership/person-4.png' then raise exception 'Incorrect image: {members,3,image}'; end if;
if (select data#>>'{members,4,image}' from public.cms_sections where page_id='company--leadership' and key='sectionFour') is distinct from '/our-company/leadership/person-5.png' then raise exception 'Incorrect image: {members,4,image}'; end if;
if (select data#>>'{credentials,0,image}' from public.cms_sections where page_id='company--certifications-recognitions' and key='sectionThree') is distinct from '/our-company/certifications-and-recognitions/certificate-1.png' then raise exception 'Incorrect image: {credentials,0,image}'; end if;
if (select data#>>'{credentials,1,image}' from public.cms_sections where page_id='company--certifications-recognitions' and key='sectionThree') is distinct from '/our-company/certifications-and-recognitions/certificate-2.png' then raise exception 'Incorrect image: {credentials,1,image}'; end if;
if (select data#>>'{credentials,2,image}' from public.cms_sections where page_id='company--certifications-recognitions' and key='sectionThree') is distinct from '/our-company/certifications-and-recognitions/certificate-3.png' then raise exception 'Incorrect image: {credentials,2,image}'; end if;
if (select data#>>'{credentials,3,image}' from public.cms_sections where page_id='company--certifications-recognitions' and key='sectionThree') is distinct from '/our-company/certifications-and-recognitions/certificate-4.png' then raise exception 'Incorrect image: {credentials,3,image}'; end if;
if (select data#>>'{credentials,4,image}' from public.cms_sections where page_id='company--certifications-recognitions' and key='sectionThree') is distinct from '/our-company/certifications-and-recognitions/certificate-5.png' then raise exception 'Incorrect image: {credentials,4,image}'; end if;
if (select data#>>'{credentials,5,image}' from public.cms_sections where page_id='company--certifications-recognitions' and key='sectionThree') is distinct from '/our-company/certifications-and-recognitions/certificate-6.png' then raise exception 'Incorrect image: {credentials,5,image}'; end if;
if (select data#>>'{credentials,6,image}' from public.cms_sections where page_id='company--certifications-recognitions' and key='sectionThree') is distinct from '/our-company/certifications-and-recognitions/certificate-7.png' then raise exception 'Incorrect image: {credentials,6,image}'; end if;
if (select data#>>'{credentials,7,image}' from public.cms_sections where page_id='company--certifications-recognitions' and key='sectionThree') is distinct from '/our-company/certifications-and-recognitions/certificate-8.png' then raise exception 'Incorrect image: {credentials,7,image}'; end if;
if (select data#>'{members,5}' from public.cms_sections where page_id='company--leadership' and key='sectionFour')<>'{}'::jsonb then raise exception 'Cleared member recreated'; end if;
if exists(select 1 from public.cms_sections where page_id='company--about-us' and key='sectionOne' and (enabled or data->>'heading'<>'Edited heading' or revision<>41)) then raise exception 'Copy/visibility/revision changed'; end if;
if (select count(*) from public.cms_history where actor='System: Company page images added')<>6 then raise exception 'Wrong audit count or non-idempotent'; end if;
end $$;
